  &lt;/div&gt;
&lt;/div&gt;

&lt;!-- Responsive column stacking: 12→6→4 columns per row --&gt;
&lt;div class="container"&gt;
  &lt;div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3"&gt;
