    &lt;div class="col"&gt;&lt;div class="card p-3"&gt;Card 2&lt;/div&gt;&lt;/div&gt;
    &lt;div class="col"&gt;&lt;div class="card p-3"&gt;Card 3&lt;/div&gt;&lt;/div&gt;
  &lt;/div&gt;
